alter table public.manufacturer_notification_settings alter column assignment_enabled set default false,alter column due_soon_enabled set default false,alter column overdue_enabled set default false,alter column certificate_enabled set default false,alter column certified_dealer_enabled set default false,alter column weekly_summary_enabled set default false;
update public.manufacturer_notification_settings set assignment_enabled=false,due_soon_enabled=false,overdue_enabled=false,certificate_enabled=false,certified_dealer_enabled=false,weekly_summary_enabled=false,updated_at=now();
create or replace function public.assignment_notifications_enabled()returns boolean language plpgsql stable security definer set search_path='' as $f$declare mid uuid;begin select active_manufacturer_id into mid from public.profiles where id=auth.uid();if mid is null or not private.has_manufacturer_role(mid,array['owner','admin','content_manager']::public.manufacturer_role[])then return false;end if;return coalesce((select assignment_enabled from public.manufacturer_notification_settings where manufacturer_id=mid),false);end$f$;
revoke all on function public.assignment_notifications_enabled()from public,anon;grant execute on function public.assignment_notifications_enabled()to authenticated;
